#!/usr/bin/env node
// Generated by scripts/build-skill.mjs from scripts/skill/make_link.mjs in the drawcast repository (github.com/hmelberg/drawcast). Do not edit by hand: rebuild with `npm run build:skill`.
// Print the drawcast.app link that plays a drawcast.
//
//   node make_link.mjs cast.yaml
//   node make_link.mjs < cast.yaml
//   node make_link.mjs --base http://localhost:5199/ cast.yaml   (another player)
//
// The link is https://www.drawcast.app/#cast=<data>: <data> is the UTF-8 text of
// the YAML, compressed with raw DEFLATE (level 9, no zlib/gzip header) and
// written as base64url without padding. Node's standard library only.
// make_link.py prints the same link for the same file.
import { readFileSync, realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { deflateRawSync } from "node:zlib";

const BASE = "https://www.drawcast.app/";

export function makeLink(data, base = BASE) {
  let bytes = Buffer.from(data);
  // A byte-order mark is not part of the YAML.
  if (bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) bytes = bytes.subarray(3);
  new TextDecoder("utf-8", { fatal: true }).decode(bytes); // fail loudly on text that is not UTF-8
  const raw = deflateRawSync(bytes, { level: 9 });
  return `${base}#cast=${raw.toString("base64url")}`;
}

// A drawcast script's own words (the app's src/spec/script/lines.ts and detect.ts): its column-0 settings, and the
// top-level keys only a YAML or JSON spec writes.
const SETTING_RE = /^(lang|voice|level|record|feedback|affirm|heading|page|canvas|domain|vars|text|zoom_from|book|style|credits|board|use|with|adjust|details|sources|more|end_page|role|chapter|subtitle|advance|gap|transitions|next|enroll|prompt|comments|views|poster|tags|format|thumb|voices):(\s|$)/;
const SPEC_KEY_RE = /^(title|elements|commands|template|params|playlist|assets|subtitles|text_map|templates|audio)\s*:/;

/** How many spoken lines the drawcast has, near enough: a YAML spec's `speak:` fields, or a script's (.cast) speech lines. */
export function spokenLines(text) {
  const speaks = (text.match(/(?<![\w-])"?speak"?\s*:/g) ?? []).length;
  return speaks > 0 ? speaks : scriptLines(text) ?? 0;
}

/** A script's speech lines: column 0, not a heading, setting, comment or goto, outside a fence. Null when the text is no script. */
function scriptLines(text) {
  let fenced = false, ink = false, n = 0;
  for (const raw of text.replace(/\r\n?/g, "\n").split("\n")) {
    const body = raw.trim();
    if (body.startsWith("```")) { fenced = !fenced; continue; }
    if (fenced || body === "") continue;
    if (/^[ \t]/.test(raw)) { ink = true; continue; } // a stage direction
    if (SPEC_KEY_RE.test(body)) return null; // a YAML spec
    if (/^#{1,2}(\s|$)/.test(body)) { ink = true; continue; }
    if (body.startsWith("//") || /^@[A-Za-z_][A-Za-z0-9_-]*$/.test(body) || SETTING_RE.test(body)) continue;
    n++;
  }
  return ink ? n : null;
}

function main(argv) {
  const args = [...argv];
  let base = BASE;
  const at = args.indexOf("--base");
  if (at !== -1) {
    base = args[at + 1];
    args.splice(at, 2);
  }
  const data = args[0] && args[0] !== "-" ? readFileSync(args[0]) : readFileSync(0);
  if (!data.toString("utf8").trim()) {
    console.error("make_link: no YAML given (a file name, or the YAML on stdin)");
    process.exit(1);
  }
  const link = makeLink(data, base);
  console.log(link);
  console.error(`${spokenLines(data.toString("utf8"))} spoken lines (the default brief is 14–20; a length the user asked for wins)`);
  if (link.length > 16000) console.error(`note: the link is ${link.length} characters; if the chat cuts it, give the YAML and https://www.drawcast.app/#paste instead`);
}

// Run as a script (not imported): compare real paths, since /tmp and the like are symlinks on some systems.
if (process.argv[1] && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1])) main(process.argv.slice(2));
